<?php require 'config/functions.php';
$data=$_GET['data']??date('Y-m-d');$d=DateTime::createFromFormat('!Y-m-d',$data);if(!$d||$d->format('Y-m-d')!==$data) $data=date('Y-m-d');
$sql="SELECT f.id,f.data_frete,f.status,t.nome AS transportador,o.nome AS origem,d.nome AS destino, GROUP_CONCAT(CONCAT(p.nome,' (',fp.quantidade,'x)') SEPARATOR '; ') AS produtos FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos o ON o.id=f.origem_id JOIN enderecos d ON d.id=f.destino_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id WHERE f.data_frete=? GROUP BY f.id,f.data_frete,f.status,t.nome,o.nome,d.nome ORDER BY f.id";
$s=$pdo->prepare($sql);$s->execute([$data]);$rows=$s->fetchAll();
if(isset($_GET['baixar'])&&$_GET['baixar']==='csv') {
 header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="fretes-'.$data.'.csv"');
 $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Frete','Data','Transportador','Origem','Destino','Produtos','Status'],';');
 foreach($rows as $r) fputcsv($out,[$r['id'],$r['data_frete'],$r['transportador'],$r['origem'],$r['destino'],$r['produtos'],$r['status']],';'); fclose($out);exit;
}
require 'header.php'; ?>
<section class="hero"><div class="eyebrow">CONSULTAS</div><h1>Relatório de fretes</h1><p class="text-secondary">Selecione uma data e baixe os fretes em CSV, que abre no Excel.</p></section><div class="panel mb-4"><form method="get" class="row g-3 align-items-end"><div class="col-md-5"><label class="form-label">Data do frete</label><input class="form-control" type="date" name="data" value="<?= h($data) ?>" required></div><div class="col-auto"><button class="btn btn-primary">Consultar</button></div><div class="col-auto"><a class="btn btn-outline-primary" href="relatorio.php?data=<?= urlencode($data) ?>&baixar=csv">Baixar CSV</a></div></form></div>
<div class="panel"><h2 class="h5 fw-bold mb-3">Resultados: <?= count($rows) ?> frete(s)</h2><?php if(!$rows): ?><p class="text-secondary">Nenhum frete nessa data.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Nº</th><th>Transportador</th><th>Origem</th><th>Destino</th><th>Produtos</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= $r['id'] ?></td><td><?= h($r['transportador']) ?></td><td><?= h($r['origem']) ?></td><td><?= h($r['destino']) ?></td><td><?= h($r['produtos']) ?></td><td><?= h($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php require 'footer.php'; ?>